    fn MoxaAgentX_TableNew(name: *const c_char) -> *mut c_void;
    fn MoxaAgentX_TableAddIndex(tbl: *mut c_void, asn_type: c_int) -> c_int;
    fn MoxaAgentX_TableAddColumn(tbl: *mut c_void, col: c_uint, asn_type: c_int) -> c_int;
    fn MoxaAgentX_RowNew() -> *mut c_void;
    fn MoxaAgentX_RowAddIndex(
