agentx::init("app_moxa_framework");
// Plan E fix-1 PoC: self-contained demo table_data_set at .8691.602.99.1 —
// proves net-snmp serves GET/GETNEXT/GETBULK for a framework-owned table
// (walk/bulkwalk .1.3.6.1.4.1.8691.602.99 should return 3 rows x 2 cols).
const DEMO_TABLE: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 99, 1];
agentx::register_demo_table(DEMO_TABLE);
// Plan E (ADR-0003): trustedIp columns are dual-registered with in-master.
// Register them as column subtrees (same OID length as in-master), not as
// per-row instances — otherwise longer namelen makes framework win the wire
// and GETNEXT times out. Map still keeps instance rows for GET lookup.
const TRUSTEDIP: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 1, 4, 1, 2];
let mut trustedip_cols = std::collections::HashSet::<Vec<agentx::Oid>>::new();
for oid in lib_moxa_rust_ies_auto_mibs::all_oids() {
    let under_trustedip = oid.len() > TRUSTEDIP.len()
        && oid.iter().zip(TRUSTEDIP.iter()).all(|(a, b)| a == b);
    if under_trustedip {
        let col = oid[..oid.len() - 1].to_vec();
        if trustedip_cols.insert(col.clone()) {
            agentx::register_handler(
                "moxaIesConfig",
                &col,
                agentx::HANDLER_CAN_RWRITE,
                moxa_config_handler,
            );
        }
        continue;
    }
    agentx::register_instance(
        "moxaIesConfig",
        &oid,
        agentx::HANDLER_CAN_RWRITE,
        moxa_config_handler,
    );

