/// Parse a dotted IPv4 string ("192.168.1.5") to 4 bytes. None if malformed.
fn ipv4_to_bytes(s: &str) -> Option<[u8; 4]> {
    let mut out = [0u8; 4];
    let mut n = 0usize;
    for part in s.split('.') {
        if n >= 4 {
            return None;
        }
        out[n] = part.parse::<u8>().ok()?;
        n += 1;
    }
    if n == 4 {
        Some(out)
    } else {
        None
    }
}

/// Plan E (ADR-0003, fix-1): build trustedIp as a read-only `table_data_set` from
/// running config so net-snmp serves GET/GETNEXT/GETBULK. Columns:
/// 1=index(INTEGER), 2=ipAddress(IPADDRESS), 3=netmask(IPADDRESS),
/// 4=rowStatus(INTEGER active(1)/notInService(2)). SET stays in-master; this is
/// GET-only. Built once at startup (PoC — refresh-on-config-change is future work).
fn register_trustedip_table(state: &SubagentState, root: &[agentx::Oid]) {
    let rows = match read_config_value(state, "trustedAccess/trustedIp") {
        Ok(v) => v.as_array().cloned().unwrap_or_default(),
        Err(_) => Vec::new(),
    };

    let tbl = agentx::table_new("trustedIpTable");
    if tbl.is_null() {
        return;
    }
    agentx::table_add_index(tbl, agentx::ASN_INTEGER);
